let language='es',category=0;
const dialog=document.querySelector('#product-dialog');
const content=document.querySelector('#dialog-content');
function render(){
 const t=copy[language],idx=language==='es'?0:1;
 document.documentElement.lang=language;
 document.title=language==='es'?'AleDesign Objects — propuesta de tienda 3D':'AleDesign Objects — 3D shop concept';
 for(const el of document.querySelectorAll('[data-i18n]'))el.textContent=t[el.dataset.i18n];
 for(const el of document.querySelectorAll('[data-alt]'))el.setAttribute('aria-label',t[el.dataset.alt]);
 document.querySelector('#close-dialog').setAttribute('aria-label',t.close);
 document.querySelector('#theme').setAttribute('aria-label',t.theme);
 document.querySelector('#theme').title=t.theme;
 document.querySelector('#filters').setAttribute('aria-label',t.filterLabel);
 for(const button of document.querySelectorAll('[data-language]'))button.setAttribute('aria-pressed',String(button.dataset.language===language));
 const filters=document.querySelector('#filters');filters.replaceChildren();
 t.categories.forEach((label,index)=>{const button=document.createElement('button');button.type='button';button.textContent=label;button.setAttribute('aria-pressed',String(index===category));button.addEventListener('click',()=>{category=index;render();document.querySelectorAll('#filters button')[index].focus({preventScroll:true})});filters.append(button)});
 const visible=products.filter(p=>!category||p.category===category),grid=document.querySelector('#products');grid.replaceChildren();
 document.querySelector('#count').textContent=`${String(visible.length).padStart(2,'0')} ${t.pieces}`;
 for(const p of visible){const article=document.createElement('article');article.className='product';article.innerHTML=`<button type="button" class="product-image-link" aria-label="${t.detail}: ${p.names[idx]}"><div class="product-image crop-${p.id}" role="img" aria-label="${p.alts[idx]}"></div><span class="image-tag">${t.render}</span></button><div class="product-heading"><h3>${p.names[idx]}</h3><span class="product-category">${t.categories[p.category]}</span></div><p class="product-description">${p.descriptions[idx]}</p><div class="product-tail"><span>${t.price}</span><button class="text-button" type="button">${t.detail} <span aria-hidden="true">↗</span></button></div>`;for(const b of article.querySelectorAll('button'))b.addEventListener('click',()=>openProduct(p));grid.append(article)}
}
function openProduct(p){const t=copy[language],i=language==='es'?0:1;content.innerHTML=`<div class="dialog-grid"><div class="product-image crop-${p.id}" role="img" aria-label="${p.alts[i]}"></div><div class="dialog-copy"><p class="eyebrow">${t.concept} / 0${p.id+1}</p><h2 id="dialog-title">${p.names[i]}</h2><p>${p.descriptions[i]}</p><dl class="dialog-meta"><div><dt>${t.material}</dt><dd>PLA · ${t.pending}</dd></div><div><dt>${t.dimensions}</dt><dd>${t.pending}</dd></div><div><dt>${t.price}</dt><dd>${t.pending}</dd></div><div><dt>${t.delivery}</dt><dd>${t.deliveryValue}</dd></div></dl><p class="dialog-notice">${t.dialogNotice}</p></div></div>`;dialog.showModal()}
for(const button of document.querySelectorAll('[data-language]'))button.addEventListener('click',()=>{language=button.dataset.language;render()});
document.querySelector('#theme').addEventListener('click',()=>document.documentElement.classList.toggle('dark'));
document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});
document.querySelector('#custom-button').addEventListener('click',()=>{const t=copy[language];content.innerHTML=`<div class="custom-dialog"><p class="eyebrow">${t.customLabel}</p><h2 id="dialog-title">${t.customTitle}</h2><p>${t.customNotice}</p></div>`;dialog.showModal()});
render();
